import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadSambharLakeData(){const e=readFileSync(resolve(__dirname,"../../frontend/sambhar-lake-explorer/sambhar-lake-data.js"),"utf-8");return new Function(e+"\nreturn { SAMBHAR_LAKE_INFO, ECOLOGY_HYDROLOGY, WILDLIFE_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Sambhar Lake Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadSambharLakeData()}),describe("SAMBHAR_LAKE_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.SAMBHAR_LAKE_INFO.id).toBe("sambhar-lake-explorer"),expect(e.SAMBHAR_LAKE_INFO.name).toContain("Sambhar"),expect(e.SAMBHAR_LAKE_INFO.ramsarYear).toBe(1990),expect(e.SAMBHAR_LAKE_INFO.ramsarSiteNo).toBe(464),expect(e.SAMBHAR_LAKE_INFO.state).toBe("Rajasthan")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.SAMBHAR_LAKE_INFO.quickStats)).toBe(!0),expect(e.SAMBHAR_LAKE_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains saltProduction, flamingos, ramsarSite, history, geography, and wildlife",()=>{expect(e.ECOLOGY_HYDROLOGY.saltProduction).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.flamingos).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.ramsarSite).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.history).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.geography).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.wildlife).toBeDefined()})}),describe("WILDLIFE_SPECIES catalog",()=>{it("is a non-empty array of species",()=>{expect(Array.isArray(e.WILDLIFE_SPECIES)).toBe(!0),expect(e.WILDLIFE_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Greater Flamingo",()=>{const t=e.WILDLIFE_SPECIES.find(e=>"greater-flamingo"===e.id);expect(t).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"sambhar-lake"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../sambhar-lake-explorer/index.html")})})});